            sum_squares += elem ** 2
    return math.sqrt(sum_squares)

def operator_norm(A):
    m, n = len(A), len(A[0])
    max_row_sum = 0
    for i in range(m):
        row_sum = 0
        for j in range(n):
            row_sum += abs(A[i][j])
        if row_sum > max_row_sum:
            max_row_sum = row_sum
    return max_row_sum

